var bootstrapDiscoveryEngineCmekMu sync.Mutex

// BootstrapDiscoveryEngineCmekKey ensures that a shared KMS key exists in `location`,
// grants the Discovery Engine service agent Encrypter/Decrypter access on that key,
// and ensures an ACTIVE non-default Discovery Engine CmekConfig is registered for it.
//
// A persistent CmekConfig is required because DataStore deletion is asynchronous in the
// backend and prevents deleting a connected CmekConfig immediately during test teardown.
func BootstrapDiscoveryEngineCmekKey(t *testing.T, location, keyShortName, cmekConfigID string) string {
	t.Helper()

	kmsKey := kms.BootstrapKMSKeyWithPurposeInLocationAndName(t, "ENCRYPT_DECRYPT", location, keyShortName)
	kmsKeyName := kmsKey.CryptoKey.Name

	if os.Getenv("VCR_PATH") != "" && os.Getenv("VCR_MODE") == "REPLAYING" {
		return kmsKeyName
	}

	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return ""
	}

	bootstrapDiscoveryEngineCmekMu.Lock()
	defer bootstrapDiscoveryEngineCmekMu.Unlock()

	projectID := envvar.GetTestProjectFromEnv()
	baseURL := strings.ReplaceAll(transport_tpg.BaseUrl(discoveryengine.Product, config), "{{location}}", location)
	listURL := fmt.Sprintf("%sprojects/%s/locations/%s/cmekConfigs", baseURL, projectID, location)
	cmekURL := fmt.Sprintf("%s/%s", listURL, cmekConfigID)

	// Check if any existing CmekConfig in this location already protects kmsKeyName.
	if listRes, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   projectID,
		RawURL:    listURL,
		UserAgent: config.UserAgent,
		Timeout:   5 * time.Minute,
	}); err == nil {
		if rawConfigs, ok := listRes["cmekConfigs"].([]interface{}); ok {
			for _, raw := range rawConfigs {
				cfg, ok := raw.(map[string]interface{})
				if !ok {
					continue
				}
				if cfg["kmsKey"] == kmsKeyName {
					state, _ := cfg["state"].(string)
					if state == "ACTIVE" {
						return kmsKeyName
					}
					if state == "CREATING" {
						if name, ok := cfg["name"].(string); ok && name != "" {
							waitForDiscoveryEngineCmekConfigActive(t, config, projectID, fmt.Sprintf("%s%s", baseURL, name))
							return kmsKeyName
						}
					}
				}
			}
		}
	}

	// Check the target cmekConfigID directly.
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "GET",
		Project:   projectID,
		RawURL:    cmekURL,
		UserAgent: config.UserAgent,
		Timeout:   5 * time.Minute,
	})
	if err == nil {
		state, _ := res["state"].(string)
		switch state {
		case "ACTIVE":
			return kmsKeyName
		case "CREATING":
			waitForDiscoveryEngineCmekConfigActive(t, config, projectID, cmekURL)
			return kmsKeyName
		case "UNUSABLE", "DELETED":
			log.Printf("[DEBUG] DiscoveryEngine CmekConfig %q is in state %q; re-provisioning", cmekURL, state)
		default:
			t.Fatalf("Bootstrapped DiscoveryEngine CmekConfig %q is in unexpected state %q", cmekURL, state)
		}
	} else if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		t.Fatalf("Error reading DiscoveryEngine CmekConfig %q: %s", cmekURL, err)
	}

	rmService := rmClient.NewClient(config, config.UserAgent)
	project, err := rmService.Projects.Get(projectID).Do()
	if err != nil {
		t.Fatalf("Error getting project %q: %s", projectID, err)
	}

	// Best-effort ensure the Discovery Engine service agent exists for the project.
	genIdentityURL := fmt.Sprintf("https://serviceusage.googleapis.com/v1beta1/projects/%d/services/discoveryengine.googleapis.com:generateServiceIdentity", project.ProjectNumber)
	if _, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "POST",
		Project:   projectID,
		RawURL:    genIdentityURL,
		UserAgent: config.UserAgent,
		Timeout:   2 * time.Minute,
	}); err != nil {
		log.Printf("[DEBUG] generateServiceIdentity for discoveryengine returned: %v", err)
	}

	ensureCryptoKeyEncrypterDecrypter(t, config, kmsKeyName, fmt.Sprintf("serviceAccount:service-%d@gcp-sa-discoveryengine.iam.gserviceaccount.com", project.ProjectNumber))

	createURL := fmt.Sprintf("%s?setDefault=false", cmekURL)
	body := map[string]interface{}{
		"kmsKey": kmsKeyName,
	}

	var op map[string]interface{}
	deadline := time.Now().Add(3 * time.Minute)
	for {
		op, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "PATCH",
			Project:   projectID,
			RawURL:    createURL,
			UserAgent: config.UserAgent,
			Body:      body,
			Timeout:   60 * time.Minute,
		})
		if err == nil {
			break
		}
		if time.Now().Before(deadline) && (transport_tpg.IsGoogleApiErrorWithCode(err, 400) || transport_tpg.IsGoogleApiErrorWithCode(err, 403)) {
			log.Printf("[DEBUG] Retrying CmekConfig %q creation while KMS IAM propagates: %v", cmekConfigID, err)
			time.Sleep(15 * time.Second)
			continue
		}
		t.Fatalf("Error creating DiscoveryEngine CmekConfig %q: %s", cmekURL, err)
	}

	if err := discoveryengine.DiscoveryEngineOperationWaitTime(
		config, op, projectID, location, "Bootstrapping DiscoveryEngine CmekConfig",
		config.UserAgent, 60*time.Minute,
	); err != nil {
		t.Fatalf("Error waiting for DiscoveryEngine CmekConfig %q provisioning operation: %s", cmekURL, err)
	}

	waitForDiscoveryEngineCmekConfigActive(t, config, projectID, cmekURL)
	return kmsKeyName
}

func waitForDiscoveryEngineCmekConfigActive(t *testing.T, config *transport_tpg.Config, projectID, cmekURL string) {
	t.Helper()
	deadline := time.Now().Add(60 * time.Minute)
	for {
		res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "GET",
			Project:   projectID,
			RawURL:    cmekURL,
			UserAgent: config.UserAgent,
			Timeout:   5 * time.Minute,
		})
		if err != nil {
			t.Fatalf("Error polling DiscoveryEngine CmekConfig %q: %s", cmekURL, err)
		}
		state, _ := res["state"].(string)
		if state == "ACTIVE" {
			return
		}
		if state != "CREATING" {
			t.Fatalf("DiscoveryEngine CmekConfig %q entered unexpected state %q while waiting for ACTIVE", cmekURL, state)
		}
		if !time.Now().Before(deadline) {
			t.Fatalf("Timed out waiting for DiscoveryEngine CmekConfig %q to become ACTIVE", cmekURL)
		}
		time.Sleep(15 * time.Second)
	}
}

func ensureCryptoKeyEncrypterDecrypter(t *testing.T, config *transport_tpg.Config, kmsKeyName, member string) {
	t.Helper()
	const role = "roles/cloudkms.cryptoKeyEncrypterDecrypter"
	kmsClient := kms.NewClient(config, config.UserAgent)

	backoff := time.Second
	for {
		policy, err := kmsClient.Projects.Locations.KeyRings.CryptoKeys.GetIamPolicy(kmsKeyName).Do()
		if err != nil {
			t.Fatalf("Error getting IAM policy for KMS key %q: %s", kmsKeyName, err)
		}

		alreadyGranted := false
		foundRole := false
		for _, binding := range policy.Bindings {
			if binding.Role == role {
				foundRole = true
				if slices.Contains(binding.Members, member) {
					alreadyGranted = true
				} else {
					binding.Members = append(binding.Members, member)
				}
				break
			}
		}
		if alreadyGranted {
			return
		}
		if !foundRole {
			policy.Bindings = append(policy.Bindings, &cloudkms.Binding{
				Role:    role,
				Members: []string{member},
			})
		}

		_, err = kmsClient.Projects.Locations.KeyRings.CryptoKeys.SetIamPolicy(kmsKeyName, &cloudkms.SetIamPolicyRequest{
			Policy: policy,
		}).Do()
		if err == nil {
			log.Printf("[DEBUG] Granted %s on %s to %s; waiting 15s for IAM propagation", role, kmsKeyName, member)
			time.Sleep(15 * time.Second)
			return
		}
		if tpgresource.IsConflictError(err) && backoff <= 30*time.Second {
			time.Sleep(backoff)
			backoff *= 2
			continue
		}
		t.Fatalf("Error setting IAM policy on KMS key %q: %s", kmsKeyName, err)
	}
}
